package invoicing;

import static readcode.Assert.*;

import java.util.List;
import java.util.Map;

public class InvoiceTest {
    static final class MapSource implements RateSource {
        final Map<String, Integer> rates;
        int lookups;

        MapSource(Map<String, Integer> rates) {
            this.rates = rates;
        }

        @Override
        public int basisPointsFor(String region) {
            lookups++;
            return rates.get(region);
        }
    }

    public void testTaxIsRoundedHalfUp() {
        TaxPolicy policy = new TaxPolicy(new MapSource(Map.of("NY-A", 875)));
        assertEquals(88, policy.taxCents("NY-A", 1000));
        assertEquals(0, policy.taxCents("NY-A", 5));
    }

    public void testInvoiceTotalsAcrossLines() {
        InvoiceService service = new InvoiceService(new TaxPolicy(new MapSource(Map.of("TX-A", 625))));
        Invoice invoice = service.issue("acme", List.of(
                new LineItem("widget", 3, 1000, "TX-A"),
                new LineItem("gadget", 1, 2500, "TX-A")));
        assertEquals(5500, invoice.netCents());
        assertEquals(344, invoice.taxCents());
        assertEquals(5844, invoice.totalCents());
    }

    public void testPolicyAsksItsSourceOncePerRegion() {
        MapSource source = new MapSource(Map.of("WA-A", 1000));
        TaxPolicy policy = new TaxPolicy(source);
        policy.taxCents("WA-A", 100);
        policy.taxCents("WA-A", 200);
        assertEquals(1, source.lookups, "rate for the same region was looked up repeatedly");
    }

    public void testTwoPoliciesWithDifferentSourcesDoNotShareRates() {
        TaxPolicy us = new TaxPolicy(new MapSource(Map.of("DE-1", 0)));
        TaxPolicy eu = new TaxPolicy(new MapSource(Map.of("DE-1", 1900)));
        long usTax = us.taxCents("DE-1", 10_000);
        long euTax = eu.taxCents("DE-1", 10_000);
        System.out.println("tax for the same region from two policies: " + usTax + " and " + euTax);
        assertEquals(0, usTax);
        assertEquals(1900, euTax, "second policy saw the rate of the first policy's source");
    }

    public void testRateChangeInNewSourceIsPickedUpByNewService() {
        TaxPolicy before = new TaxPolicy(new MapSource(Map.of("FR-1", 2000)));
        Invoice first = new InvoiceService(before).issue("c1", List.of(new LineItem("a", 1, 10_000, "FR-1")));
        assertEquals(2000, first.taxCents());
        TaxPolicy after = new TaxPolicy(new MapSource(Map.of("FR-1", 2200)));
        Invoice second = new InvoiceService(after).issue("c2", List.of(new LineItem("a", 1, 10_000, "FR-1")));
        assertEquals(2200, second.taxCents(), "new rate ignored after the rate table was replaced");
    }

    public void testMixedRegionsOnOneInvoice() {
        InvoiceService service = new InvoiceService(new TaxPolicy(new MapSource(Map.of("OR-1", 0, "CA-1", 725))));
        Invoice invoice = service.issue("c3", List.of(
                new LineItem("a", 1, 10_000, "OR-1"),
                new LineItem("b", 2, 5_000, "CA-1")));
        assertEquals(725, invoice.taxCents());
        assertEquals(20_725, service.totalBilled());
    }

    public void testFormattedInvoice() {
        InvoiceService service = new InvoiceService(new TaxPolicy(new MapSource(Map.of("NV-1", 800))));
        Invoice invoice = service.issue("c5", List.of(new LineItem("desk", 2, 12_345, "NV-1")));
        String text = InvoiceFormatter.render(invoice);
        assertTrue(text.contains("total 266.65"), text);
        assertEquals(Map.of("NV-1", 1975L), service.taxByRegion());
    }

    public void testEmptyInvoiceRejected() {
        InvoiceService service = new InvoiceService(new TaxPolicy(new MapSource(Map.of())));
        assertThrows(IllegalArgumentException.class, () -> service.issue("c4", List.of()));
    }
}
